/**
 * TEMPORARY, THROWAWAY DEMO — not intended to merge. See the PR this ships on for context: it
 * exists purely to show the shared ZimmProductCard component family (PR #85) live, against real
 * SFCC product data, from the homepage, via this repo's ephemeral MRT preview environment.
 *
 * Renders all 11 states ZimmProductCard's own Storybook story set already covers
 * (organisms/zimmProductCard/index.stories.tsx), reusing ONE real fetched product's data as the
 * shared base and overriding only the specific prop(s) each state needs — the same
 * `{...Default.args, <override>}` pattern that story file already uses, just with a real product
 * substituted for its hand-authored SVG fixture. Add-to-bag is fully real (the same
 * `addItemToNewOrExistingBasket` mutation the PDP uses); `onNotifyMe`/`onRemove` are demo-only
 * toasts, since no such mutation exists anywhere in this codebase to wire them to for real.
 *
 * Known, un-fixed gap: `ZimmProductCardContent`'s bag button has no loading-spinner slot at all
 * (only `isUnavailable` exists as a lever) — a slow add-to-bag request shows no in-button pending
 * state. Not fixed here; that would be scope creep onto a broadly-consumed shared component for a
 * throwaway demo page.
 */
import React, { useMemo, useState } from 'react';
import { useIntl } from 'react-intl';
import { Box, Stack, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import Section from '@salesforce/retail-react-app/app/components/section';
import {
  useProductSearch,
  useShopperBasketsV2MutationHelper as useShopperBasketsMutationHelper,
} from '@salesforce/commerce-sdk-react';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { HOME_SHOP_PRODUCTS_LIMIT } from '../../constants';
import { ZimmProductCard } from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
import {
  pickDemoHit,
  selectLiveProductCardBase,
  buildSizeChipValues,
  type LiveDemoSourceHit,
} from './liveProductCardDemoMapper';

/**
 * Page-local, unexported adaptation of organisms/zimmProductCard/index.stories.tsx's own
 * `LiveSizeSelectionCard` — same narrowing reasoning that file documents: attaching
 * `selectedSizeChipValue`/`onSizeChipSelect` onto an *unnarrowed* prop spread fails `tsc` on the
 * `home` union branch, so narrow via the `variation` discriminant first.
 */
const DemoSizeSelectableCard = (props: ZimmProductCardProps) => {
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(() =>
    props.variation === 'plp' || props.variation === 'wishlist' ? props.selectedSizeChipValue : undefined,
  );
  const isSizeChipVariation = props.variation === 'plp' || props.variation === 'wishlist';
  const onSizeChipSelectFromProps = isSizeChipVariation ? props.onSizeChipSelect : undefined;
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    onSizeChipSelectFromProps?.(value);
  };
  const propsWithLiveSelection: ZimmProductCardProps = isSizeChipVariation
    ? { ...props, selectedSizeChipValue, onSizeChipSelect: handleSizeChipSelect }
    : props;
  return <ZimmProductCard {...propsWithLiveSelection} />;
};

export const LiveProductCardDemoSection = () => {
  const intl = useIntl();
  const showToast = useToast();
  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();

  const {
    data: productSearchResult,
    isLoading: isSearchLoading,
    isError: isSearchError,
    error: searchError,
  } = useProductSearch({
    parameters: {
      // Confirmed live (2026-09-05): HOME_SHOP_PRODUCTS_CATEGORY_ID ('newarrivals') is a generic
      // base-template sample category with zero real hits in Zimmermann's actual catalog -- the
      // existing "Shop Products" section elsewhere on this page has this exact same latent gap.
      // A free-text query is independent of category taxonomy entirely, so it doesn't matter that
      // the real category structure is unknown/undocumented -- confirmed more robust for a
      // throwaway demo than guessing at a real cgid.
      q: 'dress',
      htype: 'master',
      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
      perPricebook: true,
      allVariationProperties: true,
      limit: HOME_SHOP_PRODUCTS_LIMIT,
    },
  });

  // TEMPORARY diagnostic, throwaway-demo only: render the actual fetch state visibly instead of
  // silently returning null on any failure, so this is debuggable from the page itself.
  console.log('[live-demo] search state', {
    isSearchLoading,
    isSearchError,
    searchError,
    hitCount: productSearchResult?.hits?.length,
    firstHit: productSearchResult?.hits?.[0],
  });
  console.log(
    '[live-demo] raw imageGroups of first hit',
    JSON.stringify((productSearchResult?.hits?.[0] as { imageGroups?: unknown })?.imageGroups, null, 2),
  );

  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });

  const demoHit = useMemo(
    () => pickDemoHit((productSearchResult?.hits ?? []) as LiveDemoSourceHit[]),
    [productSearchResult],
  );
  const demoProduct = useMemo(() => (demoHit ? selectLiveProductCardBase(demoHit, formatPrice) : null), [demoHit]);
  const sizeChipValues = useMemo(() => (demoHit ? buildSizeChipValues(demoHit) : []), [demoHit]);

  const handleAddToBagAsync = async () => {
    if (!demoProduct) return;
    try {
      await addItemToNewOrExistingBasket([
        { productId: demoProduct.variantProductId, price: demoProduct.variantPrice, quantity: 1 },
      ]);
      showToast({ title: 'Added to bag', status: 'success' });
    } catch (error) {
      showToast({
        title: error instanceof Error ? error.message : 'Could not add to bag',
        status: 'error',
      });
    }
  };
  // ZimmProductCard's onAddToBag is () => void -- wrap the async handler so we never hand a
  // Promise-returning function to a void-expecting prop (the try/catch above already handles
  // rejection, so there's nothing left for a caller to await or catch here).
  const handleAddToBag = () => {
    void handleAddToBagAsync();
  };
  const demoNotifyMe = () => showToast({ title: 'Notify me (demo only)', status: 'info' });
  const demoRemove = () => showToast({ title: 'Removed from wishlist (demo only)', status: 'info' });

  // TEMPORARY diagnostic, throwaway-demo only: render the actual reason nothing shows, instead of
  // silently returning null on any of loading/error/empty-hits/unusable-hit.
  if (isSearchLoading) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text>Loading live product data…</Text>
      </Section>
    );
  }
  if (isSearchError) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text color="red.500">
          Product search failed: {searchError instanceof Error ? searchError.message : String(searchError)}
        </Text>
      </Section>
    );
  }
  if (!productSearchResult?.hits?.length) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text color="orange.500">Product search returned zero hits for this category/refinement.</Text>
      </Section>
    );
  }
  if (!demoProduct) {
    return (
      <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
        <Text color="orange.500">
          Got {productSearchResult.hits.length} hit(s), but none had a usable productName to build a card from.
        </Text>
      </Section>
    );
  }

  const { base, colour, size } = demoProduct;
  const hasMultipleImages = Boolean(base.images && base.images.length > 1);

  const plpBase: ZimmProductCardProps = {
    ...base,
    id: 'live-demo-plp',
    variation: 'plp',
    badge: 'Runway',
    onAddToBag: handleAddToBag,
    sizeChipValues,
    onSizeChipSelect: () => {},
  };
  const wishlistBase: ZimmProductCardProps = {
    ...base,
    id: 'live-demo-wishlist',
    variation: 'wishlist',
    badge: 'Runway',
    colour: colour ?? 'Colour',
    size: size ?? 'Size',
    onRemove: demoRemove,
    onAddToBag: handleAddToBag,
    sizeChipValues,
    onSizeChipSelect: () => {},
  };
  const homeBase: ZimmProductCardProps = {
    ...base,
    id: 'live-demo-home',
    variation: 'home',
    badge: 'Runway',
  };

  const instances: Array<{ label: string; card: ZimmProductCardProps; interactive: boolean }> = [
    { label: 'Default (PLP)', card: plpBase, interactive: true },
    {
      label: 'PLP — Out of stock',
      card: { ...plpBase, id: 'live-demo-plp-oos', isUnavailable: true, onNotifyMe: demoNotifyMe },
      interactive: true,
    },
    { label: 'Home', card: homeBase, interactive: false },
    {
      label: 'Home — Out of stock',
      card: { ...homeBase, id: 'live-demo-home-oos', isUnavailable: true, onNotifyMe: demoNotifyMe },
      interactive: false,
    },
    { label: 'Wishlist', card: wishlistBase, interactive: true },
    {
      label: 'Wishlist — Out of stock',
      card: { ...wishlistBase, id: 'live-demo-wishlist-oos', isUnavailable: true, onNotifyMe: demoNotifyMe },
      interactive: true,
    },
    {
      label: 'Single image',
      card: { ...plpBase, id: 'live-demo-single', hoverImage: undefined, images: undefined },
      interactive: true,
    },
    {
      label: 'Multiple images',
      card: hasMultipleImages
        ? { ...plpBase, id: 'live-demo-multi', hoverImage: undefined }
        : { ...plpBase, id: 'live-demo-multi' },
      interactive: true,
    },
    {
      label: 'With sale price',
      card: {
        ...plpBase,
        id: 'live-demo-sale',
        originalPrice:
          typeof demoProduct.variantPrice === 'number'
            ? formatPrice(demoProduct.variantPrice * 1.4, demoHit?.currency ?? 'USD')
            : undefined,
      },
      interactive: true,
    },
    {
      label: 'One size',
      card: { ...plpBase, id: 'live-demo-onesize', sizeChipValues: [{ value: 'os', label: 'One size' }] },
      interactive: false,
    },
    {
      label: 'Loading price',
      card: { ...plpBase, id: 'live-demo-loading', currentPrice: undefined, isPriceLoading: true },
      interactive: true,
    },
  ];

  return (
    <Section padding={4} paddingTop={16} title="Live Product Card Demo (Temporary)">
      <Stack pt={8} spacing={8} direction="row" wrap="wrap">
        {instances.map(({ label, card, interactive }) => (
          <Box key={card.id} width="288px">
            <Text textStyle="body2" marginBottom={2}>
              {label}
            </Text>
            {interactive ? <DemoSizeSelectableCard {...card} /> : <ZimmProductCard {...card} />}
          </Box>
        ))}
      </Stack>
    </Section>
  );
};

export default LiveProductCardDemoSection;

/**
 * Pure mapping from a real `useProductSearch` hit to `ZimmProductCardProps`-shaped pieces, for the
 * temporary live homepage demo (`liveProductCardDemoSection.tsx`). No React/react-intl import, same
 * discipline `overrides/app/pages/product-detail/productInfo.ts` already establishes — a formatter
 * is injected as a parameter instead, so this stays independently callable/testable.
 *
 * Throwaway-demo scope note: this file intentionally does not attempt full type-safety against the
 * real `commerce-sdk-isomorphic` `ProductSearchHit` shape (AGENTS.md's "don't re-declare SDK types"
 * rule is aimed at production code) — the narrow, hand-rolled types below only declare the handful
 * of fields this demo actually reads, and every accessor degrades gracefully (returns `undefined`/
 * an empty array) rather than throwing when a real response doesn't have what's expected.
 */
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type {
  ZimmProductCardBaseProps,
  ZimmProductCardImage,
} from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';

export type LiveDemoImage = { link: string; disBaseLink?: string; alt?: string };
export type LiveDemoImageGroup = {
  viewType: string;
  variationAttributes?: Array<{ id: string; values?: Array<{ value: string }> }>;
  images: LiveDemoImage[];
};
export type LiveDemoVariationAttributeValue = { value: string; name?: string; orderable?: boolean };
export type LiveDemoVariationAttribute = {
  id: string;
  name?: string;
  values?: LiveDemoVariationAttributeValue[];
};
export type LiveDemoVariant = {
  productId: string;
  price?: number;
  orderable?: boolean;
  variationValues?: Record<string, string>;
};
export type LiveDemoSourceHit = {
  productId: string;
  productName?: string;
  price?: number;
  currency?: string;
  orderable?: boolean;
  imageGroups?: LiveDemoImageGroup[];
  variationAttributes?: LiveDemoVariationAttribute[];
  variants?: LiveDemoVariant[];
};

/** Injected so this module stays free of react-intl, mirroring productInfo.ts's FormatPrice shape. */
export type FormatPrice = (amount: number, currency: string) => string;

const COLOUR_ATTRIBUTE_ID = 'color';
const SIZE_ATTRIBUTE_ID = 'size';

/** Picks the demo's one real, sellable line item: first orderable variant, else variants[0], else the master hit. */
export const resolveDemoVariant = (hit: LiveDemoSourceHit) => {
  const variant = hit.variants?.find((v) => v.orderable) ?? hit.variants?.[0];
  return {
    productId: variant?.productId ?? hit.productId,
    price: variant?.price ?? hit.price,
    colourCode: variant?.variationValues?.[COLOUR_ATTRIBUTE_ID],
    sizeCode: variant?.variationValues?.[SIZE_ATTRIBUTE_ID],
  };
};

/** Cross-references a variation code (not a display name) against variationAttributes for its label. */
const resolveAttributeName = (hit: LiveDemoSourceHit, attributeId: string, code?: string): string | undefined =>
  hit.variationAttributes?.find((a) => a.id === attributeId)?.values?.find((v) => v.value === code)?.name;

export type LiveDemoCardBase = {
  base: Pick<
    ZimmProductCardBaseProps,
    'href' | 'name' | 'headingLevel' | 'primaryImage' | 'hoverImage' | 'images' | 'currentPrice'
  >;
  colour?: string;
  size?: string;
  variantProductId: string;
  variantPrice?: number;
};

/** Base fields shared by every demo card instance, built once per hit. Returns null if unusable. */
export const selectLiveProductCardBase = (
  hit: LiveDemoSourceHit,
  formatPrice: FormatPrice,
): LiveDemoCardBase | null => {
  if (!hit.productName) return null;
  const variant = resolveDemoVariant(hit);
  const colour = resolveAttributeName(hit, COLOUR_ATTRIBUTE_ID, variant.colourCode);
  const size = resolveAttributeName(hit, SIZE_ATTRIBUTE_ID, variant.sizeCode);

  const groups = filterImageGroups(hit.imageGroups ?? [], {
    viewType: 'medium',
    variationValues: variant.colourCode ? { [COLOUR_ATTRIBUTE_ID]: variant.colourCode } : {},
  }) as LiveDemoImageGroup[];
  const groupImages = groups?.[0]?.images ?? [];

  const toCardImage = (img: LiveDemoImage): ZimmProductCardImage => ({
    src: img.disBaseLink || img.link,
    // ZimmProductCardMediaImage.alt is required + non-empty (unlike base ProductTile's decorative
    // alt: '' convention) -- prefer SFCC's own alt when present, else synthesize from name+colour.
    alt: img.alt?.trim() || `${hit.productName}${colour ? `, ${colour}` : ''}`,
  });

  return {
    base: {
      href: productUrlBuilder({ id: hit.productId }),
      name: hit.productName,
      headingLevel: 'h3',
      primaryImage: groupImages[0] ? toCardImage(groupImages[0]) : toCardImage({ link: '', alt: hit.productName }),
      hoverImage: groupImages[1] ? toCardImage(groupImages[1]) : undefined,
      images: groupImages.length > 1 ? groupImages.map(toCardImage) : undefined,
      // No hardcoded fallback currency -- if either is absent, skip formatting rather than guess.
      currentPrice:
        typeof variant.price === 'number' && hit.currency ? formatPrice(variant.price, hit.currency) : undefined,
    },
    colour,
    size,
    variantProductId: variant.productId,
    variantPrice: variant.price,
  };
};

/**
 * Size-chip values for the interactive picker instances. The 'size' attribute id is the standard
 * SFCC convention but not independently confirmed against a live response this session (unlike
 * 'color', which is already an established literal elsewhere in this codebase) -- degrades to an
 * empty array rather than throwing if this org's real id differs.
 */
export const buildSizeChipValues = (hit: LiveDemoSourceHit): ZimmSizeChipValue[] =>
  (hit.variationAttributes?.find((a) => a.id === SIZE_ATTRIBUTE_ID)?.values ?? []).map((v) => ({
    value: v.value,
    label: v.name ?? v.value,
    isDisabled: v.orderable === false,
  }));

/** Picks which of the fetched hits becomes the one reused demo product. */
export const pickDemoHit = (hits: LiveDemoSourceHit[]): LiveDemoSourceHit | undefined => {
  const imageCount = (hit: LiveDemoSourceHit) =>
    (filterImageGroups(hit.imageGroups ?? [], { viewType: 'medium', variationValues: {} }) as LiveDemoImageGroup[])?.[0]
      ?.images?.length ?? 0;
  const sizeCount = (hit: LiveDemoSourceHit) =>
    hit.variationAttributes?.find((a) => a.id === SIZE_ATTRIBUTE_ID)?.values?.length ?? 0;
  return hits.find((h) => imageCount(h) >= 2 && sizeCount(h) >= 2) ?? hits.find((h) => imageCount(h) >= 1) ?? hits[0];
};

