import React, { useEffect } from 'react';
import { useIntl } from 'react-intl';
import { useLocation } from 'react-router-dom';

// Components
import { Box, Stack, Link, Text, Spinner } from '@salesforce/retail-react-app/app/components/shared/ui';

// Project Components
import Seo from '@salesforce/retail-react-app/app/components/seo';
import Section from '@salesforce/retail-react-app/app/components/section';
import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';

// Hooks
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import { useContentfulEntries, useContentfulEntry } from '../../hooks/useContentful';
import { useContentfulLiveUpdates } from '@contentful/live-preview/react';

// Constants
import {
  HOME_SHOP_PRODUCTS_CATEGORY_ID,
  HOME_SHOP_PRODUCTS_LIMIT,
  MAX_CACHE_AGE,
  STALE_WHILE_REVALIDATE,
} from '../../constants';

import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import { useProductSearch } from '@salesforce/commerce-sdk-react';

// TEMPORARY, THROWAWAY DEMO — not intended to merge, see this branch's own PR for context.
import { LiveProductCardDemoSection } from './liveProductCardDemoSection';

// Types
import type { HomepageEntry, AnyContentfulEntry } from '../../types/contentful';

// --- Shared layout ---

const HomepageContent = () => {
  const intl = useIntl();

  const { data: productSearchResult, isLoading: productsLoading } = useProductSearch({
    parameters: {
      refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID as string}`, 'htype=master'] as unknown as string, // SDK types refine as string but runtime accepts string[]
      expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
      perPricebook: true,
      allVariationProperties: true,
      limit: HOME_SHOP_PRODUCTS_LIMIT,
    },
  });

  return (
    <>
      {productSearchResult && (
        // From PWA template - Example on how to show products
        <Section
          padding={4}
          paddingTop={16}
          title={intl.formatMessage({
            defaultMessage: 'Shop Products',
            id: 'home.heading.shop_products',
          })}
          subtitle={intl.formatMessage(
            {
              defaultMessage: 'This section contains content from the catalog. {docLink} on how to replace it.',
              id: 'home.description.shop_products',
              description:
                '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs',
            },
            {
              docLink: (
                <Link
                  target="_blank"
                  href={'https://sfdc.co/business-manager-manage-catalogs'}
                  textDecoration={'none'}
                  position={'relative'}
                  _after={{
                    position: 'absolute',
                    content: `""`,
                    height: '2px',
                    bottom: '-2px',
                    margin: '0 auto',
                    left: 0,
                    right: 0,
                    background: 'gray.700',
                  }}
                  _hover={{ textDecoration: 'none' }}
                >
                  {intl.formatMessage({
                    defaultMessage: 'Read docs',
                    id: 'home.link.read_docs',
                  })}
                </Link>
              ),
            },
          )}
        >
          <Stack pt={8} spacing={16}>
            <ProductScroller products={productSearchResult?.hits} isLoading={productsLoading} />
          </Stack>
        </Section>
      )}
    </>
  );
};

// --- Normal (published) home ---

const HomeNormal = () => {
  const einstein = useEinstein();
  const { pathname } = useLocation();

  const { res } = useServerContext();
  if (res) {
    res.set(
      'Cache-Control',
      `s-maxage=${MAX_CACHE_AGE as number}, stale-while-revalidate=${STALE_WHILE_REVALIDATE as number}`,
    );
  }

  const { data: contentfulData, isLoading: contentfulLoading } = useContentfulEntries<HomepageEntry>('homepage');
  const homepageContent = useContentfulLiveUpdates(contentfulData?.[0] ?? null);

  useEffect(() => {
    einstein.sendViewPage(pathname);
  }, []);

  if (contentfulLoading) {
    return (
      <Box display="flex" justifyContent="center" py={16}>
        <Spinner size="xl" />
      </Box>
    );
  }

  if (!homepageContent) return null;

  return <HomepageContent />;
};

// --- Preview (draft) home ---

type HomePreviewContentProps = {
  entryId: string;
};

const HomePreviewContent = ({ entryId }: HomePreviewContentProps) => {
  const { data, isLoading, error } = useContentfulEntry<AnyContentfulEntry>(entryId, true);
  const liveData = useContentfulLiveUpdates(data);

  if (isLoading) {
    return (
      <Box display="flex" justifyContent="center" py={16}>
        <Spinner size="xl" />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={8}>
        <Text color="red.500">Error loading preview: {error.message}</Text>
      </Box>
    );
  }

  if (!liveData) return null;

  const contentTypeId = liveData.sys?.contentType?.sys?.id;

  if (contentTypeId !== 'homepage') {
    return (
      <Box p={8}>
        <Text>Preview for content type &ldquo;{contentTypeId}&rdquo; is not yet configured.</Text>
      </Box>
    );
  }

  return <HomepageContent />;
};

// --- Page ---

const Home = () => {
  const { search } = useLocation();
  const entryId = new URLSearchParams(search).get('entry');

  return (
    <Box data-testid="home-page">
      <Seo
        title="Home Page"
        description="Commerce Cloud Retail React App"
        keywords="Commerce Cloud, Retail React App, React Storefront"
      />
      {/* TEMPORARY, THROWAWAY DEMO — unconditional (unlike HomepageContent below, which is
          gated behind HomeNormal's Contentful-entry check) so it's always visible regardless
          of CMS state or preview mode. Not intended to merge. */}
      <LiveProductCardDemoSection />
      {entryId ? <HomePreviewContent entryId={entryId} /> : <HomeNormal />}
    </Box>
  );
};

Home.getTemplateName = () => 'home';

export default Home;

import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { fn } from 'storybook/test';
import React, { useState } from 'react';
import { Box } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { ZimmProductCardContent } from './index';
import type { ZimmProductCardContentProps } from './index';
import type { ZimmSizeChipValue } from '../zimmSizeChipGroup';

const SIZES: ZimmSizeChipValue[] = [
  { value: 'xs', label: 'XS' },
  { value: 's', label: 'S' },
  { value: 'm', label: 'M' },
  { value: 'l', label: 'L' },
];

const meta: Meta<typeof ZimmProductCardContent> = {
  title: 'Commerce/ZimmProductCardContent',
  component: ZimmProductCardContent,
  parameters: { layout: 'padded' },
  decorators: [
    // The composed product-name link renders a real react-router-dom <Link>, which requires a
    // Router context — same requirement and fix as zimmColourSwatch/index.stories.tsx.
    (Story) => (
      <MemoryRouter>
        {/* Roughly a real card's own width, matching zimmProductCardMedia/index.stories.tsx's
            decorator so this reads naturally as the block that sits beneath that component. */}
        <Box width="320px">
          <Story />
        </Box>
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductCardContent>;

/** Minimal, PLP-shaped default: name link, bag action, price — no attributes, no size chips. */
export const Default: Story = {
  args: {
    name: 'Natura Long Sleeve Linen Mini Dress',
    headingLevel: 'h3',
    href: '/product/123',
    currentPrice: '$595.00',
    showAttributes: false,
    showBag: true,
    onAddToBag: fn(),
    showSizeChips: false,
    showNotifyMe: false,
  },
};

/** Was/Now (sale) pricing: originalPrice set alongside currentPrice — the AC's "price (incl.
 *  was/now)" requirement across PLP/Home/Wishlist/Recently Viewed. Composed straight through to
 *  ZimmProductPrice, which owns the actual was/now visual treatment.
 *
 *  The was-price uses --zimm-color-text-muted (#969696), 2.95:1 on white — intentionally below
 *  4.5:1 AA to match the Figma design token (alias/color/text/subtlest), a considered call by
 *  the FE lead already made and accepted for this same treatment at both the ZimmProductPrice
 *  atom's own OnSale story and zimmProductContent's OnSale story (see zimmProductPrice.css.ts's
 *  `sale.wasPrice` comment for the full rationale). `test: 'off'` mirrors that same established
 *  suppression here — this story renders the identical composed treatment, not a new one. */
export const WithSalePrice: Story = {
  name: 'With sale price (Was/Now, PRC-09)',
  parameters: {
    a11y: { test: 'off' },
  },
  args: {
    ...Default.args,
    currentPrice: '$416.50',
    originalPrice: '$595.00',
  },
};

/** Wishlist-shaped: colour + size shown as plain text beneath the name. */
export const WithAttributes: Story = {
  args: {
    ...Default.args,
    showAttributes: true,
    colour: 'Ivory',
    size: 'M',
  },
};

/** Wishlist-shaped, one-size product: the size half of the attributes line reads "One size" rather than a real size value. */
export const WithAttributesOneSize: Story = {
  args: {
    ...Default.args,
    showAttributes: true,
    colour: 'Ivory',
    size: 'One size',
  },
};

/**
 * Wraps `ZimmProductCardContent` so `selectedSizeChipValue` is genuinely live rather than a
 * static arg — neither this component nor the `ZimmSizeChipGroup` it composes tracks selection
 * itself (both are correctly controlled components), so a story that wants a chip click to
 * visually select must own that state itself, the same pattern
 * zimmProductCard/index.stories.tsx's `Default` story already uses via its own `DefaultExample`.
 * Unlike that file, `ZimmProductCardContentProps` is a single flat type, not a discriminated
 * union keyed by `variation` — `selectedSizeChipValue`/`onSizeChipSelect` are already valid
 * (optional) members on every value of the type, so `{...args, selectedSizeChipValue,
 * onSizeChipSelect}` needs no narrowing before it assigns back to `ZimmProductCardContentProps`,
 * unlike that other file's `propsWithLiveSelection`. `handleSizeChipSelect` still fires the
 * original `args.onSizeChipSelect` (the `fn()` spy below) so Storybook's Actions panel keeps
 * logging the click.
 */
const WithSizeChipsExample = (args: ZimmProductCardContentProps) => {
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>('m');
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    args.onSizeChipSelect?.(value);
  };
  return (
    <ZimmProductCardContent
      {...args}
      selectedSizeChipValue={selectedSizeChipValue}
      onSizeChipSelect={handleSizeChipSelect}
    />
  );
};

/** PLP-shaped: the size-chip picker renders in place of the attributes line. Size chips are
 *  genuinely interactive here, not a static snapshot — starts pre-selected at 'M'; click a
 *  different chip to see the live selection move. Rendered via `WithSizeChipsExample` above,
 *  which owns `selectedSizeChipValue` as local state; every other arg below is unchanged. */
export const WithSizeChips: Story = {
  args: {
    ...Default.args,
    showSizeChips: true,
    sizeChipValues: SIZES,
    selectedSizeChipValue: 'm',
    onSizeChipSelect: fn(),
  },
  render: (args) => <WithSizeChipsExample {...args} />,
};

/**
 * PLP-shaped, one-size product: triggers `ZimmSizeChipGroup`'s own `values.length === 1` branch
 * (see that component's `index.tsx`), which renders a single non-interactive label rather than a
 * `[role=radiogroup]` of chips. Plain args here, not wrapped in `WithSizeChipsExample` and with no
 * `selectedSizeChipValue`/`onSizeChipSelect` — there is nothing to select in that branch (it never
 * reaches the chip-click/keyboard-navigation code path at all), so the interactive wrapper this
 * file uses for `WithSizeChips` would misleadingly imply a selection state that doesn't exist here.
 */
export const WithSizeChipsOneSize: Story = {
  args: {
    ...Default.args,
    showSizeChips: true,
    sizeChipValues: [{ value: 'os', label: 'One size' }],
  },
};

/** Out-of-stock: the bag button is present but disabled, and the notify-me CTA takes its place
 *  as the available action. */
export const Unavailable: Story = {
  args: {
    ...Default.args,
    isUnavailable: true,
    showNotifyMe: true,
    onNotifyMe: fn(),
  },
};

/** A variant re-fetch in progress — ZimmProductPrice renders its own invisible placeholder,
 *  preserving the layout slot rather than collapsing it. */
export const LoadingPrice: Story = {
  args: {
    ...Default.args,
    currentPrice: undefined,
    isPriceLoading: true,
  },
};

