const { test } = require('@playwright/test');

test('probe tab order + hit testing', async ({ page }) => {
  await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmproductcard--wishlist&viewMode=story');
  await page.waitForSelector('[data-testid="product-card"]');

  const describe = async () => page.evaluate(() => {
    const el = document.activeElement;
    if (!el || el === document.body) return null;
    return { tag: el.tagName, role: el.getAttribute('role'), label: el.getAttribute('aria-label'), text: el.textContent?.trim()?.slice(0, 30), slot: el.closest('[data-card-slot]')?.getAttribute('data-card-slot') };
  });

  console.log('--- FORWARD ---');
  for (let i = 0; i < 10; i++) {
    await page.keyboard.press('Tab');
    console.log(i, JSON.stringify(await describe()));
  }

  await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmproductcard--multiple-images&viewMode=story');
  await page.waitForSelector('[data-testid="product-card"]');
  const box = await page.locator('[data-testid="card-media-scroll"]').boundingBox();
  const hit = await page.evaluate(([x, y]) => {
    const el = document.elementFromPoint(x, y);
    return { tag: el?.tagName, closestScroll: !!el?.closest('[data-testid="card-media-scroll"]'), closestOverlayLink: !!el?.closest('a') };
  }, [box.x + box.width / 2, box.y + box.height / 2]);
  console.log('--- HIT TEST (image center) ---', JSON.stringify(hit));

  const cursor = await page.locator('[data-card-slot="media"]').evaluate((el) => getComputedStyle(el).cursor);
  console.log('--- CURSOR ---', cursor);
});
EOF
npx playwright test --config=playwright.config.js "$CLAUDE_JOB_DIR/tmp/probe.spec.js" --project=a11y-desktop --reporter=list 2>&1 | tail -60

