/*
 * SFCC-236 — real-browser accessibility regression coverage for ZimmProductCard's hover-reveal
 * mechanism (organism recipe: overrides/app/components/ui-kits/organisms/zimmProductCard/
 * zimmProductCard.css.ts, "Fix J"). jsdom/Vitest cannot prove any of this: it resolves no
 * stacking contexts, and it cannot distinguish "this selector string exists in the recipe" from
 * "a real browser actually keeps this element in the accessibility tree and tab order." See that
 * file's own docblock and this project's twinkly-swinging-umbrella plan for the full narrative.
 *
 * Targets Storybook directly (http://localhost:6006 by default, override via STORYBOOK_URL), not
 * the running retail app via RETAIL_APP_HOME like every other spec in this suite — ZimmProductCard
 * has no real page consumer yet (confirmed: grepping for imports outside its own folder finds only
 * the theme recipe registry). This is a deliberate, new pattern for this e2e suite, not an
 * oversight — Storybook already has every state this needs as a real story
 * (organisms/zimmProductCard/index.stories.tsx), rendered with real CSS in a real Chromium
 * instance. Wiring this into CI (building/serving Storybook as a step before the a11y-desktop
 * project runs) is a separate, follow-up piece of work, not attempted here.
 *
 * Every test below was written against values captured live from a running Storybook instance
 * during authoring (real tab-order sequences, real computed clip-path values) — not theorised.
 */
const { test, expect } = require('@playwright/test');

const STORYBOOK_URL = process.env.STORYBOOK_URL || 'http://localhost:6006';
const storyUrl = (id) => `${STORYBOOK_URL}/iframe.html?id=${id}&viewMode=story`;

/** Reads the focused element's identity without assuming which component it belongs to. */
const describeActiveElement = (page) =>
  page.evaluate(() => {
    const el = document.activeElement;
    if (!el || el === document.body) return null;
    return {
      tag: el.tagName,
      role: el.getAttribute('role'),
      label: el.getAttribute('aria-label'),
      text: el.textContent?.trim()?.slice(0, 40) || null,
      slot: el.closest('[data-card-slot]')?.getAttribute('data-card-slot') ?? null,
    };
  });

test.describe('ZimmProductCard hover-reveal — accessibility tree presence', { tag: ['@SFCC-236'] }, () => {
  // Proves Theory 1 of the regression is fixed: these controls must exist in the accessibility
  // tree (Playwright's `toBeAttached` — DOM presence, independent of paint) at all times, not
  // only once some hover/focus-visible condition has already matched. Before Fix J, each of these
  // used `display: 'none'` as its hidden state, which unconditionally removes an element from the
  // accessibility tree — a VoiceOver user who never triggers the `:has(:focus-visible)` heuristic
  // (a real, documented mismatch — see the recipe's own docblock) would find nothing here at all,
  // not just something hard to reach. Deliberately NOT using `toBeVisible()` anywhere in this
  // block — these controls are correctly clip-path-hidden by default; visibility is proven
  // separately by the stuck-open-non-regression test below.

  test('the size-chip radiogroup is present without any hover or focus', async ({ page }) => {
    await page.goto(storyUrl('commerce-zimmproductcard--wishlist'));
    await expect(page.getByRole('radiogroup', { name: 'Select a size' })).toBeAttached();
  });

  test('the notify-me button is present on an out-of-stock card without any hover or focus', async ({ page }) => {
    await page.goto(storyUrl('commerce-zimmproductcard--wishlist-out-of-stock'));
    await expect(page.getByRole('button', { name: 'Notify me' })).toBeAttached();
  });

  test('the carousel prev/next buttons are present on a multi-image card without any hover or focus', async ({
    page,
  }) => {
    await page.goto(storyUrl('commerce-zimmproductcard--multiple-images'));
    await expect(page.getByRole('button', { name: 'Previous image' })).toBeAttached();
    await expect(page.getByRole('button', { name: 'Next image' })).toBeAttached();
  });
});

test.describe('ZimmProductCard hover-reveal — tab-order parity', { tag: ['@SFCC-236'] }, () => {
  // Proves Theory 2 of the regression is fixed: before Fix J, these controls only existed as Tab
  // stops while `:hover`/`:has(:focus-visible)` was already true, so Shift+Tab entry from
  // something after the card landed on the last unconditionally-visible stop (the bag button),
  // skipping past controls that, at that instant, weren't tab stops at all. Verified live against
  // this exact story before writing this assertion (not assumed): the real, unbroken forward
  // sequence on the Wishlist story is close -> nameLink -> bag -> sizeChips(radio), then focus
  // exits the card (nothing else on an isolated Storybook page). Critically, pressing Shift+Tab
  // from a *completely fresh, nothing-focused-yet* page load — i.e. `:has(:focus-visible)` is
  // certainly false at the moment the key is pressed — still lands directly on the size-chip
  // radio as the very first reverse stop, confirming the reveal now depends only on focus
  // arriving, not on some other element having already triggered it first.

  test('forward Tab and reverse Shift+Tab (from a fresh, unfocused load) visit the same stops in reverse order', async ({
    page,
  }) => {
    await page.goto(storyUrl('commerce-zimmproductcard--wishlist'));

    const forward = [];
    for (let i = 0; i < 4; i += 1) {
      await page.keyboard.press('Tab');
      forward.push(await describeActiveElement(page));
    }
    // A 5th Tab exits the card entirely on this isolated Storybook page (nothing else to focus).
    await page.keyboard.press('Tab');
    expect(await describeActiveElement(page)).toBeNull();

    await page.goto(storyUrl('commerce-zimmproductcard--wishlist'));

    const backward = [];
    for (let i = 0; i < 4; i += 1) {
      await page.keyboard.press('Shift+Tab');
      backward.push(await describeActiveElement(page));
    }

    expect(backward).toEqual([...forward].reverse());
    // Pin the real, concrete sequence too — not just internal reversal-consistency — so a future
    // change that reverses BOTH directions identically (a subtler regression than losing parity)
    // still fails this test.
    expect(forward.map((el) => el.slot)).toEqual(['close', 'content', 'bag', 'sizeChips']);
  });
});

test.describe('ZimmProductCard hover-reveal — no regression on the original stuck-open bug', { tag: ['@SFCC-236'] }, () => {
  // Fix H (already shipped, unrelated to this session's work) stopped the carousel arrows staying
  // visible after a mouse click even once the mouse moved away, by switching the trigger from
  // `:focus-within` to `:has(:focus-visible)`. Fix J only changed which CSS property expresses
  // "hidden" (display -> clip-path) — this test proves that swap didn't quietly undo Fix H.
  // Reads `getComputedStyle(el).clipPath` directly rather than Playwright's default
  // `toBeVisible()`, which is primarily a bounding-box/`visibility` check and isn't guaranteed to
  // reliably reflect clip-path-based hiding.

  test('carousel arrows revert to clipped/hidden after a real mouse click, once the mouse leaves the card', async ({
    page,
  }) => {
    await page.goto(storyUrl('commerce-zimmproductcard--multiple-images'));
    const carousel = page.locator('[data-card-slot="carousel"]');
    const clipPath = () => carousel.evaluate((el) => getComputedStyle(el).clipPath);

    await expect.poll(clipPath).toBe('inset(50%)');

    const card = page.locator('[data-testid="product-card"]');
    await card.hover();
    await expect.poll(clipPath).toBe('none');

    await page.getByRole('button', { name: 'Next image' }).click();
    // Still revealed immediately after the click — the click itself must not hide it.
    await expect.poll(clipPath).toBe('none');

    // The actual regression this test guards: moving the mouse away entirely, after a click gave
    // the arrow button real DOM focus, must NOT leave the arrows stuck visible.
    await page.mouse.move(5, 5);
    await expect.poll(clipPath).toBe('inset(50%)');
  });
});

