159	  // Single piece of state, per this codebase's extract-to-hook threshold
160	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
161	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
162	  // because this build step's file manifest is limited to this component's own 4 files; a hook
163	  // would be a 5th file outside that scope.
164	  const [currentIndex, setCurrentIndex] = useState(0);
165	  const scrollContainerRef = useRef<HTMLDivElement>(null);
166	
167	  const scrollToIndex = (index: number) => {
168	    const container = scrollContainerRef.current;
169	    if (!container || typeof container.scrollTo !== 'function') return;
170	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
171	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
172	    // browser reports a real width so the requested slide scrolls fully into view.
173	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
174	  };
175	
176	  const goToRelativeSlide = (delta: 1 | -1) => {
177	    if (totalSlides <= 1) return;
178	    const next = (currentIndex + delta + totalSlides) % totalSlides;
179	    setCurrentIndex(next);
180	    scrollToIndex(next);
181	  };
182	
183	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
184	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
185	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
186	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
187	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
188	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
189	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
190	  useEffect(() => {
191	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
192	  }, [totalSlides]);
193	
194	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
195	  // capability — additive to, and independent of, the hover-capable-only arrows and the
196	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
197	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
198	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
199	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
200	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
201	    event.preventDefault();
202	    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
203	  };
204	
205	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
206	  // calls goToRelativeSlide at all. `scrollend` alone is not enough to do this live — that's
207	  // true on every browser, not just one lacking `scrollend` support: the event is only fired
208	  // once a scroll/snap gesture has fully *settled* (finger lifted, any momentum/snap animation
209	  // finished), so a dot driven by `scrollend` alone stays on the old slide for the whole
210	  // duration of an active drag and only jumps to the correct one once the gesture ends — a
211	  // real, user-visible lag, confirmed live once a related fix made the swipe gesture itself
212	  // reachable. `container.scrollLeft`, unlike `scrollend`, genuinely does update live while a
213	  // drag is in progress, so a `scroll` listener tracks it in real time — coalesced via
214	  // `requestAnimationFrame` so it updates at most once per animation frame, since native
215	  // touch-driven scrolling fires many `scroll` events per second and calling setState for
216	  // every one of them would be wasted work no frame could ever paint. `scrollend` stays
217	  // registered alongside `scroll`, unconditionally, as a final-correctness safety net — in
218	  // case the last in-frame scroll position during a fast gesture doesn't get its own
219	  // rAF-coalesced update before the browser is ready to fire the next one.
220	  useEffect(() => {
221	    const container = scrollContainerRef.current;
222	    if (!container || totalSlides <= 1) return undefined;
223	
224	    const updateIndexFromScrollPosition = () => {
225	      const slideWidth = container.clientWidth || 1;
226	      const nearest = Math.round(container.scrollLeft / slideWidth);
227	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
228	    };
229	
230	    // `rafId` both throttles (skip scheduling a second frame while one is already pending) and
231	    // lets cleanup cancel a frame that hasn't fired yet if the component unmounts/re-runs first.
232	    let rafId: number | null = null;
233	    const handleScroll = () => {
234	      if (rafId !== null) return;
235	      rafId = requestAnimationFrame(() => {
236	        rafId = null;
237	        updateIndexFromScrollPosition();
238	      });
239	    };
240	
241	    container.addEventListener('scroll', handleScroll, { passive: true });
242	    container.addEventListener('scrollend', updateIndexFromScrollPosition);
243	    return () => {
244	      container.removeEventListener('scroll', handleScroll);
245	      container.removeEventListener('scrollend', updateIndexFromScrollPosition);
246	      if (rafId !== null) cancelAnimationFrame(rafId);
247	    };
248	  }, [totalSlides]);
249	
250	  // Non-primary images are always lazy; only the first slide's own base image can opt into
251	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
252	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
253	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
254	
255	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
256	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
257	  const hasBadge = typeof badge === 'string' && badge.trim().length > 0;
258	
259	  return (
260	    <chakra.div __css={styles.root} data-card-slot={CARD_SLOT.media} onClick={onClick}>
261	      <chakra.div
262	        ref={scrollContainerRef}
263	        __css={styles.scrollContainer}
264	        data-testid="card-media-scroll"
265	        role={canNavigateByKeyboard ? 'group' : undefined}
266	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
267	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
268	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
269	      >
270	        {slideImages.map((image, index) => {
271	          const isPrimaryPosition = index === 0;
272	
273	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
274	            return (
275	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
276	                <chakra.img
277	                  src={image.src}
278	                  alt={image.alt}
279	                  data-role="hover-base"
280	                  __css={styles.hoverSwapBase}
281	                  {...imageLoadingProps(true)}
282	                />
283	                <chakra.img
284	                  src={hoverImage.src}
285	                  alt={hoverImage.alt}
286	                  data-role="hover-overlay"
287	                  __css={styles.hoverSwapOverlay}
288	                  {...imageLoadingProps(false)}
289	                />
290	              </chakra.div>
291	            );
292	          }
293	
294	          return (
295	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
296	              <chakra.img
297	                src={image.src}
298	                alt={image.alt}
299	                __css={styles.image}
300	                {...imageLoadingProps(isPrimaryPosition)}
301	              />
302	            </chakra.div>
303	          );
304	        })}
305	      </chakra.div>
306	
307	      {hasBadge && (
308	        <chakra.div __css={styles.badge} data-card-slot={CARD_SLOT.badge}>
309	          <chakra.span __css={styles.badgeLabel}>{badge}</chakra.span>
310	        </chakra.div>
311	      )}
312	
313	      {showRemove && (
314	        <chakra.button
315	          type="button"
316	          __css={styles.close}
317	          data-card-slot={CARD_SLOT.close}
318	          aria-label={removeLabel}
319	          onClick={onRemove}
320	        >
321	          <CloseIcon aria-hidden boxSize="var(--zimm-icon-size-md)" />
322	        </chakra.button>
323	      )}
324	
325	      {canPage && (
326	        <chakra.div __css={styles.carousel} data-card-slot={CARD_SLOT.carousel}>
327	          <chakra.button
328	            type="button"
329	            __css={styles.arrowButton}
330	            aria-label={intl.formatMessage(messages.previousImage)}
331	            onClick={() => goToRelativeSlide(-1)}
332	          >
333	            <ChevronLeftIcon aria-hidden />
334	          </chakra.button>
335	          <chakra.button
336	            type="button"
337	            __css={styles.arrowButton}
338	            aria-label={intl.formatMessage(messages.nextImage)}
339	            onClick={() => goToRelativeSlide(1)}
340	          >
341	            <ChevronRightIcon aria-hidden />
342	          </chakra.button>
343	        </chakra.div>
344	      )}
345	
346	      {totalSlides > 1 && (
347	        <chakra.div __css={styles.indicatorWrapper} data-card-slot={CARD_SLOT.indicator}>
348	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
349	        </chakra.div>
350	      )}
351	    </chakra.div>
352	  );
353	};
354	
355	export default ZimmProductCardMedia;
