import { chromium } from 'playwright';

const VIEWPORT = { width: 375, height: 800 };
const STORIES = [
  'commerce-zimmproductprice--on-sale',
  'commerce-zimmproductcardcontent--with-sale-price',
  'commerce-zimmproductcard--with-sale-price',
];

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: VIEWPORT });

for (const id of STORIES) {
  await page.goto(`http://localhost:6006/iframe.html?id=${id}&viewMode=story`);
  await page.waitForSelector('[data-testid="product-price"], [data-testid="product-was-price"]');

  const docScrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
  const viewportWidth = VIEWPORT.width;

  const wasBox = await page.getByTestId('product-was-price').boundingBox();
  const nowBox = await page.getByTestId('product-now-price').boundingBox();

  const sameLine = wasBox && nowBox ? Math.abs(wasBox.y - nowBox.y) < 2 : null;

  console.log(`\n=== ${id} ===`);
  console.log(`viewport width: ${viewportWidth}px | document.scrollWidth: ${docScrollWidth}px | overflow: ${docScrollWidth > viewportWidth}`);
  console.log(`wasPrice box:`, wasBox);
  console.log(`nowPrice box:`, nowBox);
  console.log(`was/now on same line: ${sameLine}`);
}

await browser.close();

