const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

// zm-tester's computed real mobile column width for this demo's SimpleGrid(columns:{base:2}),
// gap 64px, 100vw full-bleed, on 360-430px real phone widths: ~148-183px per card (outer boundary,
// before ZimmProductCardContent's own 32px-each-side mobile padding is applied internally).
const CARD_WIDTHS = [148, 165, 183];
// zm-tester's stress case: a plausible 4-figure luxury "Was" price, tighter than the story's
// existing 3-figure sample.
const STRESS_WAS = 'Was $1,995.00';
const STRESS_NOW = 'Now $1,495.00';

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 500, height: 800 } });
  await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmproductcardcontent--with-sale-price&viewMode=story');
  await page.waitForSelector('[data-testid="product-was-price"]');

  for (const width of CARD_WIDTHS) {
    for (const stress of [false, true]) {
      await page.evaluate(({ width, stress, STRESS_WAS, STRESS_NOW }) => {
        // Find the story's own meta-level decorator Box (fixed width:320px) and resize it to
        // simulate the demo's real column width — the component's own internal padding/flex
        // recipe then applies exactly as it would inside the real card.
        const was = document.querySelector('[data-testid="product-was-price"]');
        const now = document.querySelector('[data-testid="product-now-price"]');
        if (stress) {
          was.textContent = STRESS_WAS;
          now.textContent = STRESS_NOW;
        }
        // Walk up from the price element to find the fixed-width decorator (style.width set).
        let el = was;
        while (el && el.parentElement) {
          el = el.parentElement;
          if (el.style && el.style.width) {
            el.style.width = `${width}px`;
            el.style.maxWidth = `${width}px`;
            break;
          }
        }
      }, { width, stress, STRESS_WAS, STRESS_NOW });

      const docScrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
      const wasBox = await page.getByTestId('product-was-price').boundingBox();
      const nowBox = await page.getByTestId('product-now-price').boundingBox();
      const priceWrapper = await page.evaluate(() => {
        const was = document.querySelector('[data-testid="product-was-price"]');
        // priceWrapper is the was-price's container's parent (container -> p, wrapper -> div)
        const wrapperEl = was.closest('p').parentElement;
        const rect = wrapperEl.getBoundingClientRect();
        return { width: rect.width, right: rect.right };
      });

      const sameLine = Math.abs(wasBox.y - nowBox.y) < 2;
      const cardOverflow = wasBox.x + wasBox.width > priceWrapper.right + 1 || nowBox.x + nowBox.width > priceWrapper.right + 1;

      console.log(`card=${width}px stress=${stress} | docScrollWidth=${docScrollWidth} (viewport 500) | priceWrapper.width=${priceWrapper.width.toFixed(1)} | sameLine=${sameLine} | cardOverflow=${cardOverflow}`);
      console.log(`  wasPrice: x=${wasBox.x.toFixed(1)} w=${wasBox.width.toFixed(1)} y=${wasBox.y}`);
      console.log(`  nowPrice: x=${nowBox.x.toFixed(1)} w=${nowBox.width.toFixed(1)} y=${nowBox.y}`);
    }
  }

  await browser.close();
})();

