  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 500, height: 800 } });

  for (const width of CARD_WIDTHS) {
    for (const stress of [false, true]) {
      await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmproductcardcontent--with-sale-price&viewMode=story');
      await page.waitForSelector('[data-testid="product-was-price"]');

      await page.evaluate(({ width, stress, STRESS_WAS, STRESS_NOW }) => {
        const was = document.querySelector('[data-testid="product-was-price"]');
        const now = document.querySelector('[data-testid="product-now-price"]');
        if (stress) {
          was.textContent = STRESS_WAS;
          now.textContent = STRESS_NOW;
        }
        // Override every ancestor whose rendered width is exactly the story's 320px decorator
        // (Chakra emits emotion classes, not inline styles, so we override via inline style,
        // which beats a plain class selector regardless).
        let el = was;
        let depth = 0;
        while (el && depth < 10) {
          const rect = el.getBoundingClientRect();
          if (Math.round(rect.width) === 320) {
            el.style.setProperty('width', `${width}px`, 'important');
            el.style.setProperty('max-width', `${width}px`, 'important');
          }
          el = el.parentElement;
          depth++;
        }
      }, { width, stress, STRESS_WAS, STRESS_NOW });

      const docScrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
      const wasBox = await page.getByTestId('product-was-price').boundingBox();
      const nowBox = await page.getByTestId('product-now-price').boundingBox();
      const wrapperWidth = await page.evaluate(() => {
        const was = document.querySelector('[data-testid="product-was-price"]');
        const wrapperEl = was.closest('p').parentElement;
        return wrapperEl.getBoundingClientRect().width;
      });

      const sameLine = Math.abs(wasBox.y - nowBox.y) < 2;
      const cardOverflow = (wasBox.x + wasBox.width) > (wrapperWidth + 1) || (nowBox.x + nowBox.width) > (wrapperWidth + 1);

      console.log(`card=${width}px stress=${stress} | wrapperWidth=${wrapperWidth.toFixed(1)} | sameLine=${sameLine} | overflowsCard=${cardOverflow} | docScrollWidth=${docScrollWidth}`);
      console.log(`  wasPrice: x=${wasBox.x.toFixed(1)} w=${wasBox.width.toFixed(1)} y=${wasBox.y}`);
      console.log(`  nowPrice: x=${nowBox.x.toFixed(1)} w=${nowBox.width.toFixed(1)} y=${nowBox.y}`);
    }
  }

  await browser.close();
})();

