const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const STORIES = [
  { id: 'commerce-zimmsizechipgroup--default', label: 'ZimmSizeChipGroup standalone' },
  { id: 'commerce-zimmproductcardcontent--with-size-chips', label: 'ZimmProductCardContent (card context)' },
];

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1000, height: 800 } });

  for (const { id, label } of STORIES) {
    await page.goto(`http://localhost:6006/iframe.html?id=${id}&viewMode=story`);
    await page.waitForSelector('[role="radiogroup"]');

    const data = await page.evaluate(() => {
      const radiogroup = document.querySelector('[role="radiogroup"]');
      const parent = radiogroup.parentElement;
      const grandparent = parent.parentElement;
      const chips = Array.from(radiogroup.querySelectorAll('[role="radio"]'));

      const rgRect = radiogroup.getBoundingClientRect();
      const parentRect = parent.getBoundingClientRect();
      const gpRect = grandparent ? grandparent.getBoundingClientRect() : null;

      const chipRects = chips.map((c) => c.getBoundingClientRect());
      const gaps = [];
      for (let i = 1; i < chipRects.length; i++) {
        gaps.push(chipRects[i].x - (chipRects[i - 1].x + chipRects[i - 1].width));
      }

      return {
        radiogroup: { width: rgRect.width, x: rgRect.x },
        parent: { tag: parent.tagName, width: parentRect.width, x: parentRect.x },
        grandparent: gpRect ? { tag: grandparent.tagName, width: gpRect.width } : null,
        chipCount: chips.length,
        chipWidths: chipRects.map((r) => r.width),
        gaps,
        firstChipX: chipRects[0]?.x,
        lastChipRight: chipRects[chipRects.length - 1] ? chipRects[chipRects.length - 1].x + chipRects[chipRects.length - 1].width : null,
      };
    });

    console.log(`\n=== ${label} (${id}) ===`);
    console.log(`radiogroup: width=${data.radiogroup.width.toFixed(1)}px, x=${data.radiogroup.x.toFixed(1)}`);
    console.log(`parent <${data.parent.tag}>: width=${data.parent.width.toFixed(1)}px, x=${data.parent.x.toFixed(1)}`);
    if (data.grandparent) console.log(`grandparent <${data.grandparent.tag}>: width=${data.grandparent.width.toFixed(1)}px`);
    console.log(`radiogroup fills parent? ${Math.abs(data.radiogroup.width - data.parent.width) < 2 ? 'YES (stretched)' : 'NO — shrink-wrapped, radiogroup is ' + (data.parent.width - data.radiogroup.width).toFixed(1) + 'px narrower than its parent'}`);
    console.log(`chips: ${data.chipCount}, each ~${data.chipWidths[0]?.toFixed(1)}px wide`);
    console.log(`gaps between chips: ${data.gaps.map((g) => g.toFixed(1)).join(', ')}px`);
    console.log(`span from first chip start (${data.firstChipX?.toFixed(1)}) to last chip end (${data.lastChipRight?.toFixed(1)}) = ${(data.lastChipRight - data.firstChipX).toFixed(1)}px total`);
  }

  await browser.close();
})();

