  display: 'flex',
  // 'flex-start', not 'center': `nameRow`'s height is driven by however many lines the
  // product name wraps to, which grows unbounded with a long name. `center` re-centres the
  // bag icon against the WHOLE grown block, so it visibly drifts downward as the name gets
  // longer — the defect this replaces. `flex-start` anchors both children to the row's top
  // edge regardless of how many lines the name occupies, pinning the icon to the *first*
  // line specifically. The `bagWrapper` part below still carries the ~4px optical-centre
  // nudge the previous `center` value used to provide for free (name: 8px padding around a
  // 16px line-height ≈ 32px per line; icon: 4px padding around a 16px icon = 24px —
  // confirmed via get_design_context on node 40002163:41441, the real assembled Desktop/
  // Default/PLP-PDP card) — same numbers, now applied only once via a fixed margin instead
  // of being recomputed against a growing block on every render.
  alignItems: 'flex-start',
  justifyContent: 'space-between',
  // 8px — Figma: the 24px icon column starts at x=184 inside the 208px row, and the name
  // column is 176px wide (208 - 176 - 24 = 8).
  gap: 'var(--zimm-scale-xs)',
},

nameLink: {
  display: 'block',
  flex: '1 1 auto',
  minWidth: 0,
  color: 'inherit',
  textDecoration: 'none',
  _focusVisible: FOCUS_VISIBLE,
},

bagWrapper: {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  flexShrink: 0,
  // 4px — see nameRow's own comment above: recreates the optical-centre alignment against
  // the name's *first line* only ((32px line height - 24px icon height) / 2), independent
  // of how many additional lines the name wraps to.
  marginTop: 'var(--zimm-scale-2xs)',
},

