const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 500, height: 800 } });

  const cases = [
    ['ONE-LINE (short)', 'Silk Dress'],
    ['ORIGINAL (Natura...)', 'Natura Long Sleeve Linen Mini Dress'],
    ['LONG (forces wrap)', 'Natura Long Sleeve Linen Mini Dress With An Extremely Long Name To Force Wrapping Across Several Lines'],
  ];

  for (const [label, nameText] of cases) {
    await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmproductcardcontent--default&viewMode=story');
    await page.waitForSelector('[data-testid=\"product-name\"]', { timeout: 20000 });

    const result = await page.evaluate((nameText) => {
      // Override the decorator to the real Figma reference width (288px), not the story's own 320px.
      const nameEl = document.querySelector('[data-testid=\"product-name\"]');
      let el = nameEl, depth = 0;
      while (el && depth < 10) {
        const rect = el.getBoundingClientRect();
        if (Math.round(rect.width) === 320) {
          el.style.setProperty('width', '288px', 'important');
          el.style.setProperty('max-width', '288px', 'important');
        }
        el = el.parentElement; depth++;
      }
      nameEl.textContent = nameText;

      const bagButton = document.querySelector('[aria-label=\"Add to bag\"]');
      const nameRowEl = nameEl.closest('a').parentElement; // nameLink -> nameRow
      const nameRowRect = nameRowEl.getBoundingClientRect();
      const nameRect = nameEl.getBoundingClientRect();
      const bagRect = bagButton.getBoundingClientRect();
      const bagWrapperRect = bagButton.parentElement.getBoundingClientRect();

      return {
        nameRowTop: nameRowRect.top,
        nameRowHeight: nameRowRect.height,
        nameHeight: nameRect.height,
        nameTop: nameRect.top,
        bagWrapperTop: bagWrapperRect.top,
        bagTop: bagRect.top,
        bagTopRelativeToRow: bagRect.top - nameRowRect.top,
      };
    }, nameText);

    console.log('=== ' + label + ' ===');
    console.log(JSON.stringify(result, null, 2));
  }

  await browser.close();
})().catch((e) => { console.error('ERR', e.message); process.exit(1); });
