      const originalText = nameEl.textContent;
      if (nameText) nameEl.textContent = nameText;

      const bagButton = document.querySelector('[aria-label=\"Add to bag\"]');
      if (!bagButton) return { error: 'no bag button found', originalText };
      const nameRowEl = nameEl.closest('a').parentElement;
      const nameRowRect = nameRowEl.getBoundingClientRect();
      const bagRect = bagButton.getBoundingClientRect();

      return {
        usedName: nameEl.textContent,
        nameRowTop: nameRowRect.top,
        nameRowHeight: nameRowRect.height,
        bagTop: bagRect.top,
